from __future__ import annotations

import json
import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _as_dict(obj: Any) -> Any:
    if obj is None:
        return None
    if isinstance(obj, (str, int, float, bool)):
        return obj
    if isinstance(obj, list):
        return [_as_dict(item) for item in obj]
    if isinstance(obj, dict):
        return {k: _as_dict(v) for k, v in obj.items()}
    if hasattr(obj, "to_dict"):
        try:
            return obj.to_dict()
        except Exception:
            pass
    if hasattr(obj, "__dict__"):
        return {
            k: _as_dict(v)
            for k, v in vars(obj).items()
            if not k.startswith("_")
        }
    return str(obj)


def _field_text(field: Any) -> Optional[str]:
    if field is None:
        return None
    for attr in ("content", "value", "value_string", "value_number"):
        if hasattr(field, attr):
            val = getattr(field, attr)
            if val is not None:
                return str(val)
    if isinstance(field, dict):
        for key in ("content", "value", "valueString", "valueNumber"):
            if key in field and field[key] is not None:
                return str(field[key])
    return str(field)


def _extract_items(result: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []

    documents = getattr(result, "documents", None) or []
    for doc in documents:
        fields = getattr(doc, "fields", None) or {}
        line_items = fields.get("Items") or fields.get("LineItems") or fields.get("lineItems")
        if not line_items:
            continue

        value = getattr(line_items, "value_array", None) or []
        for item in value:
            item_fields = getattr(item, "value_object", None) or {}
            normalized_item: Dict[str, Any] = {}
            for k, v in item_fields.items():
                normalized_item[k] = _field_text(v)
            items.append(normalized_item)

    return items


def _normalize_expense_schema(result: Any) -> Dict[str, Any]:
    documents = getattr(result, "documents", None) or []
    doc = documents[0] if documents else None
    fields = getattr(doc, "fields", None) or {}

    def get_field(*names: str) -> Optional[str]:
        for name in names:
            if name in fields and fields[name] is not None:
                return _field_text(fields[name])
        return None

    normalized: Dict[str, Any] = {
        "vendor_name": get_field("MerchantName", "vendorName", "merchantName"),
        "invoice_number": get_field("InvoiceId", "invoiceNumber", "receiptNumber"),
        "invoice_date": get_field("InvoiceDate", "TransactionDate", "date"),
        "due_date": get_field("DueDate", "dueDate"),
        "currency": get_field("Currency", "currencyCode"),
        "subtotal": get_field("SubTotal", "subtotal"),
        "tax": get_field("TotalTax", "tax"),
        "tip": get_field("Tip", "tip"),
        "total": get_field("InvoiceTotal", "Total", "total"),
        "payment_method": get_field("PaymentDetails", "paymentMethod"),
        "purchase_order": get_field("PurchaseOrder", "purchaseOrder"),
        "address": get_field("MerchantAddress", "vendorAddress", "address"),
        "phone_number": get_field("MerchantPhoneNumber", "phoneNumber"),
        "tax_id": get_field("MerchantTaxId", "taxId"),
        "items": _extract_items(result),
        "raw": _as_dict(result),
    }

    return normalized


def normalize_expense_fields(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=document_bytes,
        content_type=content_type,
    )
    result = poller.result()

    return _normalize_expense_schema(result)


def normalize_expense_fields_from_file(path: str) -> str:
    with open(path, "rb") as f:
        normalized = normalize_expense_fields(f.read(), content_type="application/pdf")
    return json.dumps(normalized, ensure_ascii=False, indent=2)
